  "widget.compare.callout": { en: "<strong>{short}:</strong> {direction} association with price (slope = {slope}, R² = {r2pct}%). {compare}Remember: <em>association does not prove causation</em>. Omitted variables (condition, location, school district) could confound any of these relationships.", es: "<strong>{short}:</strong> asociación {direction} con el precio (pendiente = {slope}, R² = {r2pct}%). {compare}Recuerda: <em>asociación no demuestra causalidad</em>. Las variables omitidas (condición, ubicación, distrito escolar) podrían confundir cualquiera de estas relaciones.", ja: "<strong>{short}：</strong>価格との{direction}関連（傾き = {slope}、R² = {r2pct}%）。{compare}注意：<em>関連は因果関係を証明しません</em>。欠落変数（状態、立地、学区）はこれらの関係のいずれをも交絡させる可能性があります。" },
  "widget.compare.callout.compare": { en: "Compare to Size (R² = {sizePct}%). ", es: "Compara con Tamaño (R² = {sizePct}%). ", ja: "面積との比較（R² = {sizePct}%）。" },
