  "widget.compare.ctrl.var.opt.age": { en: "Age (years)", es: "Antigüedad (años)", ja: "築年数（年）" },
  "widget.compare.ctrl.var.opt.bathrooms": { en: "Bathrooms", es: "Baños", ja: "浴室数" },
